using AcxiomCRM.Data;using AcxiomCRM.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Api;
[ApiController,Route("api/customers"),Authorize] public class CustomersApiController:ControllerBase{private readonly ApplicationDbContext _db;public CustomersApiController(ApplicationDbContext db){_db=db;}public record CustomerDto(int Id,string CustomerCode,string CustomerName,string Email,string Phone,string? CompanyName,string Status);
 [HttpGet] public async Task<ActionResult<IEnumerable<CustomerDto>>> Get([FromQuery]string? q,int page=1,int pageSize=20){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var x=_db.Customers.AsQueryable();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")){var uid=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier);x=x.Where(c=>c.OwnerId==uid!.Value);}if(!string.IsNullOrWhiteSpace(q))x=x.Where(c=>c.CustomerName.Contains(q)||c.Email.Contains(q)||c.Phone.Contains(q)||(c.CompanyName!=null&&c.CompanyName.Contains(q)));return await x.OrderBy(c=>c.CustomerName).Skip((page-1)*pageSize).Take(pageSize).Select(c=>new CustomerDto(c.Id,c.CustomerCode,c.CustomerName,c.Email,c.Phone,c.CompanyName,c.Status)).ToListAsync();}
 [HttpGet("{id:int}")] public async Task<ActionResult<CustomerDto>> GetById(int id){var c=await _db.Customers.FindAsync(id);if(c==null)return NotFound();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")&&c.OwnerId!=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value)return Forbid();return new CustomerDto(c.Id,c.CustomerCode,c.CustomerName,c.Email,c.Phone,c.CompanyName,c.Status);}
 [HttpPost] public async Task<IActionResult> Create(Customer input){if(!ModelState.IsValid)return ValidationProblem(ModelState);if(await _db.Customers.AnyAsync(c=>c.Email==input.Email||c.Phone==input.Phone))return Conflict(new{message="Email or phone already exists."});input.Id=0;input.CreatedDate=DateTime.UtcNow;input.CreatedBy=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value;input.OwnerId??=input.CreatedBy;if(string.IsNullOrWhiteSpace(input.CustomerCode))input.CustomerCode="CUS-"+Guid.NewGuid().ToString("N")[..8].ToUpper();_db.Customers.Add(input);try{await _db.SaveChangesAsync();}catch(DbUpdateException){return Conflict(new{message="Customer code, email or phone must be unique."});}return CreatedAtAction(nameof(GetById),new{id=input.Id},new CustomerDto(input.Id,input.CustomerCode,input.CustomerName,input.Email,input.Phone,input.CompanyName,input.Status));}
 [HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,Customer input){var c=await _db.Customers.FindAsync(id);if(c==null)return NotFound();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager")&&c.OwnerId!=User.FindFirst(System.Security.Claims.ClaimTypes.NameIdentifier)?.Value)return Forbid();if(!ModelState.IsValid)return ValidationProblem(ModelState);if(await _db.Customers.AnyAsync(x=>x.Id!=id&&(x.Email==input.Email||x.Phone==input.Phone)))return Conflict(new{message="Email or phone already exists."});c.CustomerName=input.CustomerName;c.Email=input.Email;c.Phone=input.Phone;c.CompanyName=input.CompanyName;c.Address=input.Address;c.City=input.City;c.State=input.State;c.Status=input.Status;await _db.SaveChangesAsync();return NoContent();}
 [HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var c=await _db.Customers.FindAsync(id);if(c==null)return NotFound();if(!User.IsInRole("Admin")&&!User.IsInRole("Manager"))return Forbid();c.Status="Inactive";await _db.SaveChangesAsync();return NoContent();}}
